WITH сказ AS (SELECT r.milestone, (x[1])::int AS сказано FROM project_runs_log r JOIN project_documents d ON d.project_id = r.project_id AND d.entity_kind = 'run' AND d.entity_name = r.id JOIN scheme($1) t ON t.role = 'digest.task-count' CROSS JOIN LATERAL regexp_matches(d.content, '\|\s*' || t.value || '\s*\|\s*([0-9]+)\s+из', 'g') AS x WHERE r.project_id = $1 AND r.is_milestone) SELECT 'выжимок этапов нет: сверять диапазон не с чем' AS detail WHERE NOT EXISTS (SELECT 1 FROM project_runs_log WHERE project_id = $1 AND is_milestone) AND EXISTS (SELECT 1 FROM project_plan_milestones WHERE project_id = $1) UNION ALL SELECT с.milestone || ' — выжимка говорит ' || с.сказано || ' задач, а задачных выжимок ' || (SELECT count(*) FROM project_runs_log t2 WHERE t2.project_id = $1 AND NOT t2.is_milestone AND t2.milestone = с.milestone) FROM сказ с WHERE с.сказано <> (SELECT count(*) FROM project_runs_log t2 WHERE t2.project_id = $1 AND NOT t2.is_milestone AND t2.milestone = с.milestone) ORDER BY 1
